#!/usr/bin/env python3
"""Descriptive analysis for the synthetic incident-triage feasibility pilot.

No third-party dependencies. This program does not compare answers with the
scenario author's design notes and does not perform significance tests.
"""

from __future__ import annotations

import argparse
import csv
import json
import statistics
import sys
from collections import Counter, defaultdict
from datetime import datetime, timedelta, timezone
from itertools import combinations
from pathlib import Path

CLASSES = ("REPORT", "DO_NOT_REPORT", "NEED_INFO")
ESCALATIONS = ("ESCALATE_YES", "ESCALATE_NO")
REASON_CODES = (
    "NO_LISTED_CONSEQUENCE",
    "NO_MATERIAL_CONTRIBUTION",
    "THRESHOLD_NOT_MET",
    "SUPPORTED_NEAR_MISS",
    "NO_SUPPORTED_PATHWAY",
    "UNRESOLVED_CONSEQUENCE",
    "UNRESOLVED_CONTRIBUTION",
    "UNRESOLVED_NEAR_MISS_ELEMENT",
    "OTHER_AMBIGUITY",
)
REQUIRED_COLUMNS = (
    "reviewer_id",
    "scenario_id",
    "rule",
    "classification",
    "escalate",
    "reason_code",
    "reason",
    "active_minutes",
    "deadline_utc",
    "order_block",
)
BASE_DIR = Path(__file__).resolve().parent


class InputError(ValueError):
    """A response input is incomplete or inconsistent with the protocol."""


def parse_utc(value: str) -> datetime:
    """Parse an ISO timestamp and require an explicit UTC offset."""
    try:
        parsed = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
    except ValueError as exc:
        raise InputError(f"Invalid ISO timestamp: {value!r}") from exc
    if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
        raise InputError(f"Timestamp must be explicitly UTC: {value!r}")
    return parsed.astimezone(timezone.utc)


def format_utc(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def normalise_deadline(value: str) -> str:
    value = value.strip()
    if value == "UNKNOWN":
        return value
    return format_utc(parse_utc(value))


def expected_deadline(awareness: str) -> str:
    if not awareness.strip():
        return "UNKNOWN"
    return format_utc(parse_utc(awareness) + timedelta(hours=72))


def mean_pairwise_agreement(labels: list[str]) -> float | None:
    """Mean agreement over unordered pairs; None for fewer than two raters."""
    if len(labels) < 2:
        return None
    counts = Counter(labels)
    agreeing = sum(n * (n - 1) // 2 for n in counts.values())
    total = len(labels) * (len(labels) - 1) // 2
    return agreeing / total


def cohen_kappa(pairs: list[tuple[str, str]]) -> float | None:
    """Cohen's kappa for pooled within-scenario reviewer pairs."""
    if not pairs:
        return None
    labels = sorted({label for pair in pairs for label in pair})
    n = len(pairs)
    observed = sum(a == b for a, b in pairs) / n
    first = Counter(a for a, _ in pairs)
    second = Counter(b for _, b in pairs)
    expected = sum((first[label] / n) * (second[label] / n) for label in labels)
    if expected == 1:
        return None
    return (observed - expected) / (1 - expected)


def load_scenarios(path: Path = BASE_DIR / "scenarios.csv") -> dict[str, dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        required = {"scenario_id", "narrative", "first_confirmed_awareness_utc"}
        if not reader.fieldnames or not required.issubset(reader.fieldnames):
            raise InputError(f"Scenario file needs columns: {', '.join(sorted(required))}")
        scenarios = {row["scenario_id"]: row for row in reader}
    if len(scenarios) < 1:
        raise InputError("Scenario file is empty")
    for scenario_id, scenario in scenarios.items():
        expected_deadline(scenario["first_confirmed_awareness_utc"])
        if not scenario["narrative"].strip():
            raise InputError(f"Scenario {scenario_id} has no narrative")
    return scenarios


def load_responses(path: Path, scenarios: dict[str, dict[str, str]]) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        if not reader.fieldnames or any(column not in reader.fieldnames for column in REQUIRED_COLUMNS):
            raise InputError(f"Response file must contain columns: {', '.join(REQUIRED_COLUMNS)}")
        rows = list(reader)
    if not rows:
        raise InputError("Response file has no data rows")

    seen: set[tuple[str, str, str]] = set()
    coverage: dict[str, set[tuple[str, str]]] = defaultdict(set)
    expected_pairs = {(scenario_id, rule) for scenario_id in scenarios for rule in ("R", "N")}
    for line_number, row in enumerate(rows, start=2):
        reviewer = row["reviewer_id"].strip()
        scenario_id = row["scenario_id"].strip()
        rule = row["rule"].strip()
        prefix = f"Line {line_number}"
        if not reviewer or any(character.isspace() for character in reviewer):
            raise InputError(f"{prefix}: reviewer_id must be a non-empty de-identified token without spaces")
        if scenario_id not in scenarios:
            raise InputError(f"{prefix}: unknown scenario_id {scenario_id!r}")
        if rule not in ("R", "N"):
            raise InputError(f"{prefix}: rule must be R or N")
        if row["classification"] not in CLASSES:
            raise InputError(f"{prefix}: invalid classification {row['classification']!r}")
        if row["escalate"] not in ESCALATIONS:
            raise InputError(f"{prefix}: invalid escalation flag {row['escalate']!r}")
        if row["reason_code"] not in REASON_CODES:
            raise InputError(f"{prefix}: invalid reason_code {row['reason_code']!r}")
        if not row["reason"].strip():
            raise InputError(f"{prefix}: a short factual reason is required")
        try:
            minutes = float(row["active_minutes"])
        except ValueError as exc:
            raise InputError(f"{prefix}: active_minutes must be numeric") from exc
        if not 0 < minutes <= 240:
            raise InputError(f"{prefix}: active_minutes must be >0 and <=240")
        if row["order_block"] not in ("1", "2"):
            raise InputError(f"{prefix}: order_block must be 1 or 2")
        expected_block = "1" if rule == "R" else "2"
        if row["order_block"] != expected_block:
            raise InputError(f"{prefix}: Rule {rule} must be in order_block {expected_block}")
        try:
            actual_deadline = normalise_deadline(row["deadline_utc"])
        except InputError as exc:
            raise InputError(f"{prefix}: {exc}") from exc
        row["reviewer_id"] = reviewer
        row["scenario_id"] = scenario_id
        row["rule"] = rule
        row["active_minutes"] = str(minutes)
        row["deadline_utc"] = actual_deadline
        row["deadline_correct"] = str(
            actual_deadline == expected_deadline(scenarios[scenario_id]["first_confirmed_awareness_utc"])
        )
        key = (reviewer, scenario_id, rule)
        if key in seen:
            raise InputError(f"{prefix}: duplicate response for {key}")
        seen.add(key)
        coverage[reviewer].add((scenario_id, rule))

    if len(coverage) < 2:
        raise InputError("At least two reviewers are required for agreement analysis")
    for reviewer, observed_pairs in coverage.items():
        if observed_pairs != expected_pairs:
            missing = sorted(expected_pairs - observed_pairs)
            extra = sorted(observed_pairs - expected_pairs)
            raise InputError(f"Reviewer {reviewer} has incomplete coverage; missing={missing}, extra={extra}")
    return rows


def median_minutes(rows: list[dict[str, str]]) -> float | None:
    values = [float(row["active_minutes"]) for row in rows]
    return statistics.median(values) if values else None


def analyse(rows: list[dict[str, str]], scenarios: dict[str, dict[str, str]]) -> dict:
    reviewers = sorted({row["reviewer_id"] for row in rows})
    grouped: dict[tuple[str, str], list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        grouped[(row["scenario_id"], row["rule"])].append(row)

    scenario_results = []
    for scenario_id in scenarios:
        item: dict = {"scenario_id": scenario_id, "rules": {}}
        for rule in ("R", "N"):
            rule_rows = grouped[(scenario_id, rule)]
            labels = [row["classification"] for row in rule_rows]
            pairs = list(combinations(labels, 2))
            item["rules"][rule] = {
                "n": len(labels),
                "class_counts": dict(Counter(labels)),
                "escalation_counts": dict(Counter(row["escalate"] for row in rule_rows)),
                "reason_code_counts": dict(Counter(row["reason_code"] for row in rule_rows)),
                "mean_pairwise_agreement": mean_pairwise_agreement(labels),
                "unanimous": len(set(labels)) == 1,
                "pooled_observed_pair_agreement": (
                    sum(a == b for a, b in pairs) / len(pairs) if pairs else None
                ),
                "median_active_minutes": median_minutes(rule_rows),
                "deadline_correct": sum(row["deadline_correct"] == "True" for row in rule_rows),
                "deadline_total": len(rule_rows),
            }
        scenario_results.append(item)

    by_rule: dict = {}
    for rule in ("R", "N"):
        rule_rows = [row for row in rows if row["rule"] == rule]
        pair_labels: list[tuple[str, str]] = []
        scenario_agreements = []
        unanimous = 0
        for scenario_id in scenarios:
            labels = [row["classification"] for row in grouped[(scenario_id, rule)]]
            pair_labels.extend(combinations(labels, 2))
            agreement = mean_pairwise_agreement(labels)
            if agreement is not None:
                scenario_agreements.append(agreement)
            unanimous += int(len(set(labels)) == 1)
        by_rule[rule] = {
            "responses": len(rule_rows),
            "class_counts": dict(Counter(row["classification"] for row in rule_rows)),
            "escalation_counts": dict(Counter(row["escalate"] for row in rule_rows)),
            "mean_of_scenario_pairwise_agreement": (
                statistics.mean(scenario_agreements) if scenario_agreements else None
            ),
            "pooled_pairwise_agreement": (
                sum(a == b for a, b in pair_labels) / len(pair_labels) if pair_labels else None
            ),
            "cohen_kappa_pooled_within_scenario_pairs": cohen_kappa(pair_labels),
            "unanimous_scenarios": unanimous,
            "scenario_count": len(scenarios),
            "median_active_minutes_per_item": median_minutes(rule_rows),
            "deadline_correct": sum(row["deadline_correct"] == "True" for row in rule_rows),
            "deadline_total": len(rule_rows),
        }

    indexed = {(row["reviewer_id"], row["scenario_id"], row["rule"]): row for row in rows}
    transitions = []
    transition_counts: Counter = Counter()
    escalation_changes = 0
    for scenario_id in scenarios:
        changes = []
        for reviewer in reviewers:
            r = indexed[(reviewer, scenario_id, "R")]
            n = indexed[(reviewer, scenario_id, "N")]
            transition = f"{r['classification']}->{n['classification']}"
            transition_counts[transition] += 1
            escalation_changes += int(r["escalate"] != n["escalate"])
            if transition != f"{r['classification']}->{r['classification']}":
                changes.append({"reviewer_id": reviewer, "transition": transition})
        transitions.append({"scenario_id": scenario_id, "changes": changes})

    reviewer_timing = []
    for reviewer in reviewers:
        reviewer_timing.append({
            "reviewer_id": reviewer,
            **{
                f"rule_{rule}_median_minutes": median_minutes(
                    [row for row in rows if row["reviewer_id"] == reviewer and row["rule"] == rule]
                )
                for rule in ("R", "N")
            },
        })

    return {
        "instrument": "Incident Triage Lab feasibility pilot",
        "analysis_version": "0.1",
        "scope_warning": (
            "Synthetic, hand-written scenarios and a small non-representative reviewer sample. "
            "Descriptive results only; agreement is not validity and these are not legal conclusions."
        ),
        "reviewer_count": len(reviewers),
        "scenario_count": len(scenarios),
        "responses": len(rows),
        "by_rule": by_rule,
        "by_scenario": scenario_results,
        "paired_rule_comparison": {
            "transition_counts": dict(sorted(transition_counts.items())),
            "escalation_changes": escalation_changes,
            "paired_decisions": len(reviewers) * len(scenarios),
            "by_scenario": transitions,
        },
        "reviewer_timing": reviewer_timing,
    }


def diagnostics_csv(summary: dict) -> tuple[list[str], list[dict]]:
    fields = [
        "scenario_id", "rule", "n", "class_counts", "reason_code_counts",
        "mean_pairwise_agreement", "unanimous", "median_active_minutes",
        "deadline_correct", "deadline_total",
    ]
    output = []
    for scenario in summary["by_scenario"]:
        for rule in ("R", "N"):
            values = scenario["rules"][rule]
            output.append({
                "scenario_id": scenario["scenario_id"],
                "rule": rule,
                **{key: values[key] for key in fields if key not in ("scenario_id", "rule")},
                "class_counts": json.dumps(values["class_counts"], sort_keys=True),
                "reason_code_counts": json.dumps(values["reason_code_counts"], sort_keys=True),
            })
    return fields, output


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("responses", type=Path, help="De-identified response CSV")
    parser.add_argument("--scenarios", type=Path, default=BASE_DIR / "scenarios.csv")
    parser.add_argument("--output", type=Path, help="Write output instead of printing JSON to stdout")
    parser.add_argument("--format", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)
    try:
        scenarios = load_scenarios(args.scenarios)
        rows = load_responses(args.responses, scenarios)
        summary = analyse(rows, scenarios)
    except (InputError, OSError, csv.Error) as exc:
        parser.exit(2, f"Input error: {exc}\n")

    if args.format == "csv":
        fields, diagnostics = diagnostics_csv(summary)
        if args.output:
            args.output.parent.mkdir(parents=True, exist_ok=True)
            with args.output.open("w", newline="", encoding="utf-8") as handle:
                writer = csv.DictWriter(handle, fieldnames=fields, extrasaction="ignore")
                writer.writeheader()
                writer.writerows(diagnostics)
        else:
            writer = csv.DictWriter(sys.stdout, fieldnames=fields, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(diagnostics)
    else:
        rendered = json.dumps(summary, indent=2, sort_keys=True) + "\n"
        if args.output:
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_text(rendered, encoding="utf-8")
        else:
            sys.stdout.write(rendered)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

